const renewClaims = `-- name: RenewClaims :many
UPDATE claims c
SET expires_at = GREATEST(c.expires_at, make_interval(secs => COALESCE(c.lease_seconds, p.lease_seconds)) + $1::timestamptz)
FROM projects p
WHERE p.id = c.project_id
  AND c.org_id = $2 AND c.actor_kind = $3 AND c.actor_id = $4
  AND ($5::boolean OR c.session = $6)
  AND c.expires_at > $1::timestamptz
  AND c.expires_at - make_interval(secs => COALESCE(c.lease_seconds, p.lease_seconds) / 2.0) < $1::timestamptz
RETURNING c.card_id, c.org_id, c.project_id, c.actor_kind, c.actor_id, c.session, c.expires_at, c.created_at, c.lease_seconds, c.ending_announced_for
`

type RenewClaimsParams struct {
	Now        time.Time `db:"now"`
	OrgID      int64     `db:"org_id"`
	ActorKind  int16     `db:"actor_kind"`
	ActorID    int64     `db:"actor_id"`
	AnySession bool      `db:"any_session"`
	Session    string    `db:"session"`
}

// Only rows inside the second half of their lease are touched; expires_at is
// not indexed, so the update is heap-only. any_session is false for an
// agent, whose claims belong to the session that took them. The lease is the
// one the holder stated for the claim, else the project's.
func (q *Queries) RenewClaims(ctx context.Context, arg RenewClaimsParams) ([]Claim, error) {
	rows, err := q.db.Query(ctx, renewClaims,
		arg.Now,
		arg.OrgID,
		arg.ActorKind,
		arg.ActorID,
		arg.AnySession,
		arg.Session,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Claim
	for rows.Next() {
		var i Claim
		if err := rows.Scan(
			&i.CardID,
			&i.OrgID,
			&i.ProjectID,
			&i.ActorKind,
			&i.ActorID,
			&i.Session,
			&i.ExpiresAt,
			&i.CreatedAt,
			&i.LeaseSeconds,
			&i.EndingAnnouncedFor,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

